def progImp : ℕ → ℕ :=
fun n =>
  (have m := n;
    have total := 0;
    do
    let r ←
      forIn (List.range (n + 1)) ⟨m, total⟩ fun x r =>
          have m := r.fst;
          have total := r.snd;
          have total := total + m % 10;
          have m := m / 10;
          do
          pure PUnit.unit
          pure (ForInStep.yield ⟨m, total⟩)
    match r with
      | ⟨m, total⟩ => pure total).run
